WITH metrics AS (SELECT id, supplier_name, country, city, rating, LEAD(rating, 1) OVER (PARTITION BY country ORDER BY rating, id) AS next_rating, ROUND(rating / SUM(rating) OVER (PARTITION BY country, city), 4) AS rating_share, ROUND(rating / SUM(rating) OVER (PARTITION BY city), 4) AS rating_share_2, ROW_NUMBER() OVER (PARTITION BY city ORDER BY rating, id) AS seq_no, NTILE(3) OVER (PARTITION BY country ORDER BY rating, id) AS rating_bucket FROM suppliers) SELECT CASE WHEN rating_share_2 >= 0.61 THEN 'PREMIUM' ELSE 'STANDARD' END AS rating_share_2_tier, country, COUNT(*) FILTER (WHERE city = 'Berlin') AS berlin_rows, ROUND(SUM(seq_no) / NULLIF(COUNT(CASE WHEN country = 'JP' THEN 1 END), 0), 2) AS seq_no_per_jp FROM metrics GROUP BY CUBE (CASE WHEN rating_share_2 >= 0.61 THEN 'PREMIUM' ELSE 'STANDARD' END, country);
